package com.shopsphere.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { @Value("${app.jwt-secret}") String secret; public String token(String email,Long id){SecretKey k=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));return Jwts.builder().subject(email).claim("uid",id).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(k).compact();} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var claims=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(h.substring(7)).getPayload();var auth=new UsernamePasswordAuthenticationToken(claims.getSubject(),null,List.of());auth.setDetails(((Number)claims.get("uid")).longValue());SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}c.doFilter(r,s);} }
